const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={
  grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  leaf:'<path d="M5 19C0 4 12 2 21 3c1 11-5 19-16 16Z"/><path d="m5 19 12-12m-5 5-1-6m1 6 7 1"/>',
  file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h6"/>',
  check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M5 15v5h14v-5"/>',back:'<path d="M19 12H5m5-5-5 5 5 5"/>',copy:'<rect x="9" y="9" width="12" height="12" rx="2"/><path d="M15 5V3H3v12h2"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="3" fill="currentColor"/><circle cx="16" cy="17" r="3" fill="currentColor"/>',folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v9H3Z"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',external:'<path d="M14 3h7v7M21 3 10 14M10 3H3v18h18v-7"/>',upload:'<path d="M12 16V3m-4 4 4-4 4 4M4 15v6h16v-6"/>'
};
const icon=(key,size=17)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[key]||icons.file}</svg>`;
const wordmark=()=>`<svg width="38" height="38" viewBox="0 0 48 48" aria-hidden="true"><rect width="48" height="48" rx="14" fill="var(--poster-ink)"/><path d="M14 33C8 13 25 10 36 12C38 26 29 37 14 33Z" fill="var(--poster-soft)"/><path d="m14 34 17-16M23 25l-2-9M23 25l10 1" fill="none" stroke="var(--poster-ink)" stroke-width="2"/></svg>`;
const folderSvg=()=>`<svg viewBox="0 0 220 170" fill="none"><path d="M8 32a12 12 0 0 1 12-12h65l20 19h95a12 12 0 0 1 12 12v99H8Z" fill="var(--poster-accent)" stroke="var(--poster-ink)" stroke-opacity=".15" stroke-width="2"/><path d="M8 65a9 9 0 0 1 9-9h186a9 9 0 0 1 9 9v85H8Z" fill="var(--poster-soft)" stroke="var(--poster-line)" stroke-width="2"/><path d="M85 92h45M85 105h31" stroke="var(--poster-mute)" stroke-width="3" stroke-linecap="round"/></svg>`;
const leaves=()=>`<svg width="54" height="54" viewBox="0 0 50 50"><path d="M13 39C4 12 29 10 41 12c1 21-11 32-28 27Z" fill="#ff9a73"/><path d="m13 39 21-21M25 27l-3-11M25 27l12 1" stroke="#ff3d00" stroke-width="1.5" fill="none"/></svg>`;
const POSTER_PALETTES={sage:{ink:'#314e3f',soft:'#e6ebd5',accent:'#c1cc94',line:'#dbe2c9',mute:'#94a17a'},ink:{ink:'#34433e',soft:'#e4e8e2',accent:'#9da9a0',line:'#d8ded5',mute:'#8e9a8e'},rose:{ink:'#754b3d',soft:'#f3e2d7',accent:'#e6b296',line:'#ecd7c7',mute:'#ba9784'}};
const state={projects:[],mode:'browser',wechat:false,draftAutomation:false,platformSessions:{xiaohongshu:{status:'unchecked'},douyin:{status:'unchecked'}},view:'library',projectId:null,stage:'content',selected:0,platform:'wechat',reviewed:new Set(),filter:'all',busy:false,saveLabel:'正在载入…'};
const current=()=>state.projects.find(p=>p.id===state.projectId);
let saveTimer,saveChain=Promise.resolve(),toastTimer,hasUnsaved=false,editVersion=0,resizeObserver;
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='visible'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',error?8500:4000);}
function saveLabel(value){state.saveLabel=value;document.querySelectorAll('[data-save-label]').forEach(el=>el.textContent=value);}
async function api(url,body,method='POST'){
  const response=await fetch(url,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});
  let data;try{data=await response.json();}catch{throw new Error('本机服务暂时不可用，请保留页面并重试');}
  if(!response.ok)throw new Error(data.error||'操作未完成');return data;
}
function persistBrowser(){localStorage.setItem('xiaoxian-studio-v1',JSON.stringify(state.projects));}
function queueSave(){editVersion++;hasUnsaved=true;saveLabel('正在保存…');clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveNow().catch(handleSaveError),350);}
function handleSaveError(error){saveLabel('保存未完成');toast(error.message,true);}
function saveNow(){
  clearTimeout(saveTimer);const p=current();if(!p)return saveChain;
  saveChain=saveChain.catch(()=>{}).then(async()=>{
    const snapshotVersion=editVersion;const snapshot=structuredClone(p);snapshot.updatedAt=new Date().toISOString();
    if(state.mode==='local'){
      const {project}=await api('/api/projects/'+p.id,snapshot,'PUT');
      p.revision=project.revision;p.updatedAt=project.updatedAt;
      if(contentKey(p)===contentKey(project)&&cardKey(p)===cardKey(project)){
        p.contentApproval=project.contentApproval;p.cardApproval=project.cardApproval;
        for(const k of Object.keys(PLATFORMS))if(fingerprint({title:p.platforms[k].title,body:p.platforms[k].body,tags:p.platforms[k].tags})===fingerprint({title:project.platforms[k].title,body:project.platforms[k].body,tags:project.platforms[k].tags})){p.platforms[k].delivery=project.platforms[k].delivery;p.platforms[k].history=project.platforms[k].history;}
      }
    }else{p.updatedAt=snapshot.updatedAt;persistBrowser();}
    hasUnsaved=editVersion!==snapshotVersion;saveLabel(hasUnsaved?'正在保存…':'已保存');
  });return saveChain;
}
async function flush(){clearTimeout(saveTimer);await saveChain;if(hasUnsaved)await saveNow();}
function mutateContent(){const p=current();invalidateContent(p);state.reviewed.clear();queueSave();updatePreview();updateContentChecks();}
function updateContentChecks(){const p=current();const errors=validateContent(p);const box=$('[data-content-errors]');if(box)box.innerHTML=errors.map(x=>`<div class="check-line fail">${esc(x)}</div>`).join('');const btn=$('[data-action="confirm-content"]');if(btn)btn.disabled=errors.length>0;}
function statusOf(p){if(cardsApproved(p))return {text:'图卡已审核',class:''};if(contentApproved(p))return {text:'图卡制作中',class:'grey'};return {text:'内容待确认',class:'pending'};}
function todayLabel(date){return new Date(date).toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit',timeZone:'Asia/Shanghai'}).replace('/','.');}
function sidebar(){return `<aside class="sidebar"><button class="brand" data-action="library" aria-label="返回内容库"><img class="brand-logo" src="./xiaoxian-logo.png" alt="小苋AI圈"></button><button class="btn new-btn" data-action="new">${icon('plus',15)} 新建一期内容</button><nav><div class="nav-label">WORKSPACE</div><button class="nav-item ${state.view==='library'||state.view==='work'&&state.stage!=='cover'?'active':''}" data-action="library">${icon('grid')} 内容库</button><button class="nav-item ${state.view==='covers'||state.view==='work'&&state.stage==='cover'?'active':''}" data-action="covers">${icon('grid')} 封面制作</button><button class="nav-item ${state.view==='rules'?'active':''}" data-action="rules">${icon('settings')} 创作标准</button><button class="nav-item ${state.view==='guide'?'active':''}" data-action="guide">${icon('file')} 创作方法</button><button class="nav-item ${state.view==='materials'?'active':''}" data-action="materials">${icon('grid')} 素材字典</button></nav><div class="sidebar-foot"><div class="quiet-note">一件小事，<br>慢慢学会。</div><div class="small muted" style="margin-top:17px;line-height:1.9"><span class="status-dot"></span>${state.mode==='local'?'本机工作台':'浏览器工作台'}<br>最终发布，留给你。</div></div></aside>`;}
function header(){return `<header class="topbar"><div class="breadcrumb"><span>小苋AI圈</span><span>/</span><span class="crumb-current">${state.view==='library'?'内容库':state.view==='rules'?'创作标准':state.view==='guide'?'创作方法':state.view==='materials'?'素材字典':'内容工作台'}</span></div><div class="top-tools"><span class="small muted save-detail" data-save-label>${esc(state.saveLabel)}</span><span class="badge grey">${state.mode==='local'?'本机保存':'此浏览器保存'}</span><button class="btn text small" data-action="backup" title="备份全部内容">${icon('download',15)}<span class="backup-label">备份</span></button><div class="avatar" aria-label="小苋个人工作台">苋</div></div></header>`;}
function library(){
  const visible=state.projects.filter(p=>state.filter==='all'||cardsApproved(p));
  return `<div class="page-heading"><div><div class="eyebrow">XIAOXIAN CONTENT STUDIO</div><h1>把一件小事，讲清楚。</h1><p>从一个真实问题开始，做一组小白也能看懂的图。</p></div><button class="btn secondary" data-action="import">${icon('upload',15)} 导入内容</button></div><section class="hero"><div><div class="hero-label">外行人的 AI 学习笔记</div><h2>不急着成为专家，<br>先学会一点点。</h2><p>信息有用，表达容易理解。<br>内容确认后做图，图卡审核后填草稿。</p></div><div class="decoration" aria-hidden="true"><div class="hero-mini"><span>01 / 一个问题</span><b>电脑满了，<br>怎么办？</b>${leaves()}</div><div class="hero-mini"><span>02 / 一点理解</span><b>给代码一个<br>存档柜。</b>${leaves()}</div><div class="hero-mini"><span>03 / 一个行动</span><b>先存好，<br>再清理。</b>${leaves()}</div></div></section><div class="section-line"><h2>我的内容 <span class="small muted" style="margin-left:8px;font-weight:400">${state.projects.length} 期</span></h2><div><button class="filter ${state.filter==='all'?'active':''}" data-filter="all">全部</button><button class="filter ${state.filter==='approved'?'active':''}" data-filter="approved">已审核</button></div></div><section class="projects-grid">${visible.map(p=>{const s=statusOf(p),cover=currentCover(p),special=p.id==='github-tag-release-20261006'&&!creativeOf(p);return `<button class="project-tile" data-open="${esc(p.id)}"><div class="project-cover ${cover||special?'selected-issue-cover':creativeOf(p)?'styled-library-cover':''}">${cover?`<img src="${esc(cover.data)}" alt="${esc(p.content.topic)}">`:special?'<img src="/issues/github-tag-release-20261006/assets/cover-selected.png" alt="AI改崩了？这招救回来">':`<div class="mini-card"><small>${esc(p.content.series||'外行人的 AI 学习笔记')}</small><div class="mini-title">${esc(p.content.cards[0]?.title||p.content.topic)}</div><div class="mini-leaf">${leaves()}</div></div>`}</div><div class="project-details"><h3>${esc(p.content.topic)}</h3><div class="project-meta"><span class="badge ${s.class}">${s.text}</span><span>${p.content.cards.length} 张图 · ${todayLabel(p.updatedAt)}</span></div></div></button>`;}).join('')}<button class="new-tile" data-action="new"><div class="plus-circle">${icon('plus',19)}</div><span>下一个问题，从这里开始</span></button></section><p class="rule-foot">${icon('leaf',15)} 内容决定形式。审核由你确认，最终发布由你完成。</p>`;
}
function stepNav(p){const stages=[['content','内容'],['cover','封面'],['design','内页'],['review','审核'],['drafts','草稿']];return `<nav class="step-nav" aria-label="内容制作流程">${stages.map(([key,title],i)=>`<button class="step-tab ${state.stage===key?'active':''}" data-stage="${key}" ${!['content','cover'].includes(key)&&!contentApproved(p)||key==='drafts'&&!cardsApproved(p)?'disabled':''}><span class="step-num">${(i===0&&contentApproved(p)||i===3&&cardsApproved(p))?'✓':i+1}</span>${title}</button>${i<4?'<span class="step-arrow">→</span>':''}`).join('')}</nav>`;}
function stageHeading(title,description){return `<div class="work-heading"><h1>${title}</h1><button class="btn text small" data-action="library">${icon('back',14)} 内容库</button></div><p class="work-subtitle">${description}</p>`;}
function field(label,name,value,help='',rows=0){return `<div class="field"><label for="field-${name}">${label}</label>${rows?`<textarea id="field-${name}" data-field="${name}" rows="${rows}">${esc(value)}</textarea>`:`<input id="field-${name}" data-field="${name}" value="${esc(value)}">`}<div class="field-help"><span>${help}</span><span data-count="${name}">${count(value)} 字</span></div></div>`;}
function briefView(p){const b=p.content.brief||{audience:'',benefit:'',direction:'',references:[]};return `<details class="creative-brief"><summary>创作简报与参考图 <span class="small muted">可选，帮助这一期更贴合你的期待</span></summary><div class="brief-fields">${field('给谁看','brief-audience',b.audience,'不填时沿用小苋的外行读者定位')}${field('看完有什么收获','brief-benefit',b.benefit,'可以是理解、判断、行动或一个有价值的发现',2)}${field('这一期的方向与偏好','brief-direction',b.direction,'结构、风格、素材、不要出现的内容，都可以写在这里',3)}<label for="reference-images">参考图</label><input id="reference-images" type="file" data-reference-upload accept="image/png,image/jpeg,image/webp" multiple><p class="small muted">保存在本机项目中，不自动进入成图。最多4张，每张2MB。</p><div class="reference-grid">${b.references.map((ref,i)=>`<figure><img src="${esc(ref.data)}" alt="${esc(ref.name)}"><figcaption>${esc(ref.name)}</figcaption><textarea rows="2" data-reference-note="${i}" placeholder="喜欢它的什么：层级、构图、配色……">${esc(ref.note)}</textarea><button class="btn text small" data-action="remove-reference" data-index="${i}">移除</button></figure>`).join('')}</div><button class="btn secondary" data-action="creation-request">复制给 Codex 的创作任务</button><p class="small muted">把任务发到当前 Codex 对话执行；网页负责保存选择、照片和生成结果。</p></div></details>`;}
function blockEditor(c){return `<div class="block-editors">${(c.blocks||[]).map((b,i)=>`<section class="block-editor"><div class="row between"><label for="block-type-${i}">内容区块 ${i+1}</label><select id="block-type-${i}" data-block-index="${i}" data-block-field="type">${Object.entries(BLOCK_LABELS).map(([k,v])=>`<option value="${k}" ${b.type===k?'selected':''}>${v}</option>`).join('')}</select><button class="btn text small" data-action="remove-block" data-index="${i}">移除</button></div><input aria-label="区块 ${i+1} 小标题" data-block-index="${i}" data-block-field="heading" placeholder="小标题，可留空" value="${esc(b.heading)}"><textarea aria-label="区块 ${i+1} 内容" data-block-index="${i}" data-block-field="text" rows="4" placeholder="${b.type==='compare'?'每行一组，用 | 分隔两边内容':'填写内容；清单或步骤每行一条'}">${esc(b.text)}</textarea></section>`).join('')}</div><button class="btn secondary small" data-action="add-block" ${(c.blocks||[]).length>=20?'disabled':''}>${icon('plus',13)} 增加内容区块</button>`;}
function contentView(p){const c=p.content.cards[state.selected];return `${stageHeading('01 · 把这期内容讲明白','根据主题选择结构。先保证读者收益和必要解释，再决定怎样呈现。')}<div class="editor-grid"><section class="panel"><h2>这一期想表达什么</h2>${field('选题','topic',p.content.topic,'具体问题、发现、案例或观点都可以')}${field('核心判断 / 读者收益','takeaway',p.content.takeaway,'读者看完，理解了什么或能做什么？',2)}${briefView(p)}<div class="divider"></div><div class="row between" style="margin-bottom:16px"><h2 style="margin:0">图卡内容</h2><button class="btn text small" data-action="add-card" ${p.content.cards.length>=MAX_CARDS?'disabled':''}>${icon('plus',13)} 加一张</button></div><div class="card-tabs">${p.content.cards.map((x,i)=>`<button class="card-tab ${i===state.selected?'active':''}" data-select="${i}">第 ${i+1} 张</button>`).join('')}</div>${c?`${field('引题（可选）','card-eyebrow',c.eyebrow,'帮助理解即可，不需要每页都有')}${field('标题（可选）','card-title',c.title,'长短与层级根据内容决定',2)}${field('内容','card-body',c.body,'保留解释、案例和判断依据，是否合适看成图预览',5)}${blockEditor(c)}${field('补充说明（可选）','card-note',c.note,'用途与位置可以变化，不必固定为一句提醒',2)}<div class="row between"><label for="card-kind" style="margin:0">呈现起点</label><select id="card-kind" data-field="card-kind" style="width:auto;max-width:155px">${[['editorial','自由编排'],['cover','旧版封面'],['cabinet','旧版解释'],['steps','步骤'],['clean','旧版行动'],['prompt','提示词']].map(([k,v])=>`<option value="${k}" ${c.kind===k?'selected':''}>${v}</option>`).join('')}</select><button class="btn text small" data-action="remove-card" ${p.content.cards.length<=1?'disabled':''}>移除这一张</button></div>`:''}<div class="checks" data-content-errors></div><div class="info-box">字数与页数服务于表达。内容要有增量、有依据、容易理解；不虚构经历。版面放不下时可以换编排或拆页。</div><div class="action-bar"><span class="small muted">${contentApproved(p)?'内容已确认；修改后需重新确认。':'确认内容后，再制作正式图卡。'}</span><button class="btn primary" data-action="confirm-content">确认内容 ${icon('arrow',15)}</button></div></section>${preview(p)}</div>`;}


function preview(p){return `<section class="preview-panel"><div class="preview-meta"><span>HTML 图卡预览</span><span>3:4 · 1080 × 1440</span></div><div class="preview-stage"><div class="preview-frame"><div class="card-scale">${poster(p,state.selected)}</div></div></div><div class="thumb-row">${p.content.cards.map((x,i)=>`<button class="page-dot ${i===state.selected?'active':''}" data-select="${i}" aria-label="预览第 ${i+1} 张图卡">${i+1}</button>`).join('')}</div><div class="preview-caption">${state.selected+1} / ${p.content.cards.length} · 编排随内容调整</div></section>`;}
function designView(p){if(creativeOf(p))return `${stageHeading('制作教程内页','内页独立设计，用图形和步骤兑现封面的承诺。')}<div class="editor-grid"><section class="panel"><h2>内页设计</h2><div class="choice-row">${Object.entries(CREATIVE_STYLES).map(([key,v])=>`<button data-action="creative-style" data-style="${key}" class="${creativeOf(p).style===key?'active':''}">${v.name}</button>`).join('')}</div><p>解释用对照，操作用步骤，提示词突出输入和结果。这里调整内页配色，不改变封面的生成输入。</p><button class="btn secondary" data-stage="cover">打开封面制作</button><h2 style="margin-top:24px">第 ${state.selected+1} 张图卡</h2><div class="action-bar"><button class="btn secondary" data-action="preview-png">导出当前预览</button><button class="btn primary" data-action="go-review">去审核</button></div></section>${preview(p)}</div>`;if(p.id==='github-tag-release-20261006')return `${stageHeading('02 · 封面已选，检查整套图卡','第一张使用你选定的真人 AIGC 封面；后六张使用同系列高对比教程排版。')}<div class="editor-grid"><section class="panel"><h2>这一期的视觉已经定稿到同一方向</h2><div class="swatches" style="margin:4px 0 20px">${['#0e9def','#ffe32a','#f42b31','#111111','#ffffff'].map(c=>`<span style="background:${c};width:32px;height:32px"></span>`).join('')}</div><div class="checklist"><span>封面保留个人脸部特征，用综艺感标题吸引点开</span><span>内页用蓝、黄、红统一气质，避免像文档截图</span><span>每页只解决一个问题，保留步骤、示例和验收标准</span><span>教程页仍是可编辑 HTML，固定导出 1080 × 1440</span></div><div class="divider"></div><div class="info-box">点击右侧页码逐张检查。要改文字，回到内容环节；这一版不会自动进入任何平台草稿。</div><div class="action-bar"><button class="btn secondary" data-action="preview-png">${icon('download',15)} 导出当前预览</button><button class="btn primary" data-action="go-review">去审核 ${icon('arrow',15)}</button></div></section>${preview(p)}</div>`;return `${stageHeading('02 · 给内容一个好看的样子','这里只调整视觉。文字要改，请回到内容环节；排版变化后需要重新审核。')}<div class="editor-grid"><section class="panel"><h2>统一品牌，灵活编排</h2><label>配色</label><div class="theme-options">${[['sage','小苋绿',['#314e3f','#e6ebd5','#f9f7ef']],['ink','纸墨灰',['#34433e','#e4e8e2','#f6f5ee']],['rose','暖杏色',['#754b3d','#f3e2d7','#fdf6ee']]].map(([v,l,colors])=>`<button class="theme-option ${p.visual.theme===v?'active':''}" data-theme="${v}"><div class="swatches">${colors.map(c=>`<span style="background:${c}"></span>`).join('')}</div><b>${l}</b></button>`).join('')}</div><label>这一张的编排</label><div class="layout-options wrap">${[['flow','顺序阅读'],['split','分栏组织'],['feature','重点突出']].map(([v,l])=>`<button class="layout-choice ${p.visual.pageLayouts?.[state.selected]===v?'active':''}" data-page-layout="${v}">${l}</button>`).join('')}</div><p class="small muted">自由区块可按页组合，旧稿可切换新编排；切换后需重审。</p><label>留白</label><div class="layout-options">${[['airy','多一点呼吸'],['compact','稍紧凑一些']].map(([v,l])=>`<button class="layout-choice ${p.visual.layout===v?'active':''}" data-layout="${v}">${l}</button>`).join('')}</div><div class="divider"></div><h2>第 ${state.selected+1} 张的主图标</h2><div class="selected-material">${p.visual.artwork?.[state.selected]?materialSvg(p.visual.artwork[state.selected]):icon('leaf',42)}<div><b>${p.visual.artwork?.[state.selected]?esc(iconName(p.visual.artwork[state.selected])):'模板原图'}</b><p>图标按需要使用，颜色跟随品牌；区块承担解释。</p></div></div><div class="row wrap"><button class="btn secondary" data-action="choose-icon">浏览 8,104 个素材</button>${p.visual.artwork?.[state.selected]?'<button class="btn text small" data-action="remove-icon">恢复模板原图</button>':''}</div><div class="divider"></div><div class="checklist"><span>真人、物件或文字封面，HTML / SVG 教程内页</span><span>图形帮助理解，案例和证据清楚</span><span>字号有层级，品牌与阅读节奏一致</span><span>固定 3:4，导出 1080 × 1440 PNG</span></div><div class="divider"></div><div class="info-box">内容决定版式。可以用段落、清单、步骤或对照；参考图用于提炼视觉原则。</div><div class="action-bar"><button class="btn secondary" data-action="preview-png">${icon('download',15)} 导出当前预览</button><button class="btn primary" data-action="go-review">去审核 ${icon('arrow',15)}</button></div></section>${preview(p)}</div>`;}
function reviewView(p){return `<div class="work-heading"><h1>03 · 你看过，才算做好</h1><div class="row wrap"><button class="btn primary" data-action="review-all" ${cardsApproved(p)?'disabled':''}>${icon('check',15)} ${cardsApproved(p)?'已全部审核通过':'全部审核通过'}</button><button class="btn text small" data-action="library">${icon('back',14)} 内容库</button></div></div><p class="work-subtitle">审核页只看图、写备注、确认或退回。可以逐张检查，也可以在右上角一次确认全部图卡。</p><div class="review-grid">${p.content.cards.map((c,i)=>`<section class="review-card"><div class="review-card-head"><span>图 ${String(i+1).padStart(2,'0')} · ${esc(c.eyebrow)}</span><button class="review-check ${state.reviewed.has(i)?'checked':''}" data-reviewed="${i}" aria-pressed="${state.reviewed.has(i)}">${state.reviewed.has(i)?'✓ 已检查':'标记已检查'}</button></div><div class="preview-frame"><div class="card-scale">${poster(p,i)}</div></div></section>`).join('')}</div><div class="review-summary"><section class="panel"><h2>审核备注</h2><textarea data-field="review-note" rows="3" placeholder="哪里不好懂？哪里缺少例子、依据或操作条件？">${esc(p.reviewNote)}</textarea><div class="field-help"><span>退回对应环节修改，不在审核页直接改图。</span></div><div class="row wrap" style="margin-top:20px"><button class="btn secondary" data-stage="content">退回文字</button><button class="btn secondary" data-stage="design">退回视觉</button></div></section><section class="panel"><h2>确认前，看内容是否有用</h2><div class="checklist"><span>读者能说出收获，必要术语和例子已解释</span><span>行动建议交代条件与成功标准</span><span>文字没有裁切，重点一眼可见</span><span>事实准确，没有过度承诺</span></div><div class="action-bar"><span class="small muted">已检查 ${state.reviewed.size} / ${p.content.cards.length} 张</span><button class="btn primary" data-action="confirm-cards" ${state.reviewed.size!==p.content.cards.length?'disabled':''}>确认全部图卡 ${icon('check',15)}</button></div></section></div>`;}
function pIcon(key){return `<span class="platform-icon ${key}">${{wechat:'微',xiaohongshu:'红',douyin:'抖'}[key]}</span>`;}
function draftStatus(d){return {draft:'已写入草稿',manual:'已手动填入',unverified:'已创建 · 待核对',opening:'正在启动',queued:'等待执行',waiting_login:'等待扫码',logged_in:'已登录',unchecked:'未检查',uploading:'正在上传',filling:'正在填写',ready_to_save:'正在保存',filled:'已填好 · 待保存',needs_attention:'需要你接管',error:'未完成'}[d?.status]||'待填写';}
function draftsView(p){const k=state.platform,copy=p.platforms[k],rule=PLATFORMS[k],check=validatePlatform(p,k),automated=k!=='wechat'&&state.mode==='local'&&state.draftAutomation,session=state.platformSessions?.[k]||{status:'unchecked'},loggedIn=session.status==='logged_in';return `${stageHeading('04 · 把这一版，放进草稿','核心图卡已经锁定。这里只适配各平台配文，最终发布由你完成。')}<div class="platform-nav">${Object.entries(PLATFORMS).map(([key,value])=>`<button class="platform-btn ${key===k?'active':''}" data-platform="${key}">${pIcon(key)}${value.name}</button>`).join('')}</div><div class="editor-grid"><section class="panel"><h2>${rule.name}配文 <span class="badge grey" style="float:right">${k==='wechat'&&state.mode==='local'&&state.wechat?'接口草稿':automated?'本机自动草稿':'手动填写'}</span></h2>${field('标题','platform-title',copy.title,'不超过 20 字')}${field('说明','platform-body',copy.body,k==='douyin'?'约150字，尽量精简':'正文与话题合计不超过1000字',7)}${field('话题','platform-tags',copy.tags.join(' '),'用空格分隔，最多 '+rule.tags+' 个')}<div class="tag-list" data-tag-list>${copy.tags.map(t=>`<span class="topic-tag">#${esc(t)}</span>`).join('')}</div><div class="checks" data-platform-checks>${platformChecks(p,k)}</div><div class="action-bar"><button class="btn secondary" data-action="copy">${icon('copy',14)} 复制配文</button><button class="btn primary" data-action="package" ${check.errors.length?'disabled':''}>${icon('download',15)} 下载交付包</button></div></section><section class="panel"><h2>已审核的 ${p.content.cards.length} 张图</h2><div class="draft-mini-grid">${p.content.cards.map((c,i)=>`<div class="draft-mini">${i+1}<br>${esc(c.title)}</div>`).join('')}</div><p class="delivery-note">这份配文只使用已审核的图卡。<br>要改图卡，请返回上游重新审核。</p><div class="divider"></div><h2>三端草稿进度</h2><div class="draft-status-list">${Object.entries(PLATFORMS).map(([key,value])=>{const d=p.platforms[key].delivery;return `<div class="draft-status-row"><span class="draft-status-name">${pIcon(key)} ${value.name}</span><span class="badge ${d?.status==='draft'||d?.status==='manual'?'':'grey'}">${draftStatus(d)}</span></div>`;}).join('')}</div>${k==='wechat'?`<div class="info-box ${state.mode!=='local'||!state.wechat?'warning':''}">${state.mode==='local'&&state.wechat?'已连接本机公众号配置。只创建多图草稿，不调用发布接口。':'当前未连接公众号接口。请先下载交付包，手动填写公众号草稿。'}</div><button class="btn primary" style="width:100%;margin-top:17px" data-action="wechat-draft" ${check.errors.length||state.mode!=='local'||!state.wechat?'disabled':''}>${icon('upload',15)} ${copy.delivery?.mediaId?'核对 / 复用公众号草稿':'填写公众号草稿'}</button>${copy.delivery?.mediaId?`<p class="small muted" style="line-height:1.8;margin-top:12px">已创建的草稿保留在公众号后台；修改配文会创建新版本。</p>`:''}`:automated?`<div class="session-check"><div><b>${rule.name}登录准备</b><p>先检查独立 Chrome 的扫码登录状态，再解锁自动填写。</p></div><span class="badge ${loggedIn?'':'grey'}">${draftStatus(session)}</span></div><button class="btn secondary" style="width:100%;margin-bottom:12px" data-action="platform-login">${loggedIn?'重新检查登录状态':'检查 / 扫码登录'+rule.name}</button>${copy.delivery?.message?`<p class="delivery-note">${esc(copy.delivery.message)}</p>`:''}<button class="btn primary" style="width:100%" data-action="auto-draft" ${check.errors.length||!loggedIn?'disabled':''}>${icon('upload',15)} ${copy.delivery?.status==='draft'?'重新核对 / 填写新草稿':'自动填写'+rule.name+'草稿'}</button><p class="small muted" style="line-height:1.8;margin-top:12px">填写前还会再次校验登录状态；失效时直接停止。脚本不点击发布。</p>`:`<div class="info-box warning">当前浏览器版不能启动本机脚本。请使用本机工作台，或下载交付包后手动填写。</div><div class="row wrap" style="margin-top:17px"><a class="btn secondary" href="${k==='xiaohongshu'?'https://creator.xiaohongshu.com/':'https://creator.douyin.com/'}" target="_blank" rel="noopener">打开创作中心 ${icon('external',13)}</a><button class="btn primary" data-action="manual-draft" ${check.errors.length?'disabled':''}>我已填入草稿</button></div>`}</section></div>`;}
function platformChecks(p,k){const v=validatePlatform(p,k),rule=PLATFORMS[k];return `<div class="check-line ${v.titleLength>rule.title?'fail':''}">标题 ${v.titleLength} / ${rule.title} 字</div><div class="check-line ${v.textLength>rule.text?'fail':''}">正文＋话题 ${v.textLength} / ${rule.text} 字${k==='douyin'?' · 建议约150字':''}</div><div class="check-line ${v.tagCount>rule.tags?'fail':''}">话题 ${v.tagCount} / ${rule.tags} 个</div>${v.errors.map(t=>`<div class="check-line fail">${esc(t)}</div>`).join('')}${v.warnings.map(t=>`<div class="check-line warn">${esc(t)}</div>`).join('')}`;}
function rulesView(){return `<div class="rules-page"><div class="page-heading"><div><div class="eyebrow">CREATIVE STANDARDS</div><h1>标准要高，表达可以自由。</h1><p>用质量判断成稿，结构和版式由这一期的内容决定。</p></div></div><p class="rules-intro">你给一个主题或参考。<br>我研究、创作和自检，你确认关键版本。</p><section class="rules-card"><h2>怎样算一份好内容</h2><div class="guide-steps"><div><b>有收获</b><p>帮读者理解、判断或行动。避免几张图反复强调同一句话。</p></div><div><b>有依据</b><p>关键事实可核实，例子具体；第一人称经历必须真实。</p></div><div><b>容易读懂</b><p>用普通话解释陌生概念。必要的条件和例子不能因为追求少字而删掉。</p></div><div><b>形式合适</b><p>标题层级、页数、留白和图形按内容选择；品牌一致不等于每页相同。</p></div></div></section><section class="rules-card"><h2>让 Codex 自己走创作过程</h2><p>说“新建一期内容”，提供主题、已有材料或参考图即可。Codex 根据这一期需要选择项目 skill，研究事实，决定表达结构，完成自检并交付待确认稿。简报是可选背景，不是必须填满的表单。</p><p>参考图可以用于分析构图、层级、节奏与配色，不把示例文字或别人的经历照搬成你的事实。自由区块是编排工具，不是每期必须使用的格式。</p><p>本机网页保存项目、参考与审核记录；当前没有网页自动调用模型的接口。</p></section><section class="rules-card" style="padding:0;overflow:auto"><table class="boundary-table"><thead><tr><th>环节</th><th>负责什么</th><th>必要边界</th></tr></thead><tbody><tr><td>内容</td><td>研究、判断、事实、文字与读者收益</td><td>自行迭代，交给你确认内容；概念预览可以同步探索</td></tr><tr><td>封面</td><td>看参考、准备身份或物件素材、生成候选并挑选</td><td>封面独立；参考不代替身份，导入和选择不等于审核</td></tr><tr><td>图卡</td><td>选择或创作 HTML 编排、图形与预览</td><td>需要改已确认内容时回到内容环节；预览不代表审核通过</td></tr><tr><td>审核</td><td>看实际成图是否正确、有用、易读</td><td>由你确认最终版本，不能由程序代替</td></tr><tr><td>草稿</td><td>适配平台配文，使用审核版本交付</td><td>只保存草稿，最终发布由你执行</td></tr></tbody></table></section><section class="rules-card"><h2>可以灵活的部分</h2><p>不规定标题必须几行、每页必须有小标题、正文必须多少字或整期必须几张。可以组合段落、清单、步骤、对照和重点区块，也可以针对主题继续开发新的 HTML 版式。</p><p>1080 × 1440 是当前共用导出规格。页面需要实际检查裁切和可读性，超出画布时调整编排或拆页。文件容量和本机资源保护上限不作为创作目标。</p></section><section class="rules-card"><h2>审核与版本</h2><p>修改文字或创作简报，撤销内容确认和成图审核；修改视觉，只撤销成图审核。修改平台配文，只影响该平台草稿记录。已创建的远程草稿保留，不静默覆盖或删除。</p></section><section class="rules-card"><h2>平台交付标准</h2><table class="boundary-table"><thead><tr><th>平台</th><th>标题 / 文本</th><th>话题</th></tr></thead><tbody><tr><td>微信公众号</td><td>≤20字 / 正文与话题≤1000字</td><td>≤10个</td></tr><tr><td>小红书</td><td>≤20字 / 正文与话题≤1000字</td><td>≤10个</td></tr><tr><td>抖音</td><td>标题简短 / 文本约150字</td><td>≤5个</td></tr></tbody></table><p>公众号连接现有本机草稿接口；小红书和抖音先检查登录，再使用本机浏览器填写草稿；交付包可用于手动填写。最终发布由你执行。</p></section></div>`;}


function poster(p,i){const c=p.content.cards[i];if(!c)return '';if(creativeOf(p))return renderStyledCard(p,i);if(p.id==='github-tag-release-20261006')return renderTagReleaseCard(p,i);if(c.kind==='editorial'||c.blocks?.length||p.visual.pageLayouts?.[i])return renderFlexibleCard(p,i,wordmark(),POSTER_PALETTES[p.visual.theme]);let art='';
  if(c.kind==='cover')art=`<div class="poster-visual"><div class="folder-scene"><div class="folder-stack">${folderSvg().repeat(3)}</div><div class="arrow">→</div><div class="archive-drawer"><div class="drawer-handle">存好</div></div></div></div>`;
  if(c.kind==='cabinet')art=`<div class="poster-visual"><div class="archive-drawer"><div class="drawer-handle">我的代码</div></div><div class="archive-label">保存 · 取回 · 继续做</div></div>`;
  if(c.kind==='steps')art=`<div class="step-list">${c.body.split('\n').filter(Boolean).map((t,n)=>`<div class="poster-step"><span>${n+1}</span><p>${esc(t)}</p></div>`).join('')}</div>`;
  if(c.kind==='clean')art=`<div class="poster-visual"><div class="clean-items"><div class="clean-item">${icon('folder',78)}<span>能重新安装</span></div><div class="clean-item">${icon('file',78)}<span>能重新生成</span></div></div></div>`;
  if(c.kind==='prompt')art=`<div class="prompt-box">${esc(c.body)}</div>`;
  const chosen=p.visual.artwork?.[i];
  if(chosen)art=composeMaterialArt(c.kind,art,chosen);
  const palette=POSTER_PALETTES[p.visual.theme];
  let html=`<article class="poster ${esc(p.visual.theme)} ${esc(p.visual.layout)} ${esc(c.kind)}" data-poster="${i}"><div class="poster-header"><span class="wordmark">${wordmark()}小苋AI圈</span><span>外行人的 AI 学习笔记</span></div><div class="poster-eyebrow">${esc(c.eyebrow)}</div><h2 class="poster-title">${esc(c.title)}</h2><div class="poster-body">${esc(c.body)}</div>${art}<div class="poster-note">${esc(c.note)}</div><footer class="poster-footer"><span>一件小事，慢慢学会。</span><span class="foot-no">${String(i+1).padStart(2,'0')} / ${String(p.content.cards.length).padStart(2,'0')}</span></footer></article>`;
  for(const [key,value] of Object.entries(palette))html=html.replaceAll('var(--poster-'+key+')',value);
  return html.replaceAll('currentColor',palette.ink);
}
function chooseIcon(){
  const p=current();if(state.stage!=='design'||!contentApproved(p))throw new Error('先确认内容，再进入图卡环节选素材');
  const box=modal('给这一张，选一个符号',materialPanel(true,p.visual.artwork?.[state.selected]||''),'<button class="btn secondary" data-dismiss>取消</button>');
  box.querySelector('.modal').classList.add('material-modal');
}
function refreshMaterials(full=false){
  const panel=$('.material-browser');if(!panel)return;
  const picking=panel.dataset.picking==='true',selected=panel.dataset.selectedIcon;
  if(full)panel.outerHTML=materialPanel(picking,selected);else panel.querySelector('[data-material-results]').innerHTML=materialResults(picking,selected);
}
document.addEventListener('input',e=>{if(e.target.hasAttribute('data-cover-copy')){const p=current(),c=upgradeCover(p);c.coverCopy=c.coverCopy||{headline:'',kicker:'',points:[],benefit:''};const key=e.target.dataset.coverCopy;c.coverCopy[key]=key==='points'?e.target.value.split('\n').filter(x=>x.trim()):e.target.value;invalidateVisual(p);state.reviewed.clear();queueSave();updateCoverControls();return;}if(e.target.hasAttribute('data-cover-direction')){const p=current();upgradeCover(p).coverDirection=e.target.value;invalidateVisual(p);state.reviewed.clear();queueSave();updateCoverControls();return;}if(e.target.matches('[data-material-query]')){materialState.query=e.target.value;materialState.page=0;refreshMaterials();}});
document.addEventListener('change',e=>{if(e.target.matches('[data-material-set]')){materialState.set=e.target.value;materialState.page=0;refreshMaterials();}});
document.addEventListener('click',async e=>{
  const el=e.target.closest('[data-material-group],[data-material-page],[data-pick-icon],[data-inspect-icon],[data-download-icon]');if(!el||el.disabled||state.busy)return;
  try{
    if(el.dataset.materialGroup){materialState.group=el.dataset.materialGroup;materialState.page=0;refreshMaterials(true);return;}
    if(el.dataset.materialPage!==undefined){materialState.page=Number(el.dataset.materialPage);refreshMaterials();return;}
    if(el.dataset.pickIcon){
      await flush();const p=current();if(state.stage!=='design'||!contentApproved(p))throw new Error('素材只能在图卡环节调整');
      p.visual.artwork={...p.visual.artwork,[state.selected]:el.dataset.pickIcon};invalidateVisual(p);state.reviewed.clear();queueSave();
      el.closest('.modal-backdrop')?.remove();render();toast('主图标已选用，图卡需要重新审核。');return;
    }
    if(el.dataset.inspectIcon){const id=el.dataset.inspectIcon;modal(iconName(id),`<div class="material-detail">${materialSvg(id)}</div><p class="small muted">${esc(id)} · 矢量素材可跟随品牌配色。</p>`,`<button class="btn secondary" data-dismiss>关闭</button><button class="btn primary" data-download-icon="${esc(id)}">下载 SVG 素材包</button>`);return;}
    if(el.dataset.downloadIcon){const id=el.dataset.downloadIcon,lib=id.startsWith('lucide:')?'lucide':'tabler',zip=new JSZip();zip.file(iconName(id)+'.svg',materialSvg(id,'#314e3f'));zip.file('LICENSE.txt',await (await fetch('./licenses/'+lib+'.txt')).text());download(await zip.generateAsync({type:'blob'}),'小苋素材-'+iconName(id)+'.zip');toast('SVG 与原始许可已下载');}
  }catch(err){toast(err.message,true);}
});
function fitCards(){document.querySelectorAll('.preview-frame').forEach(frame=>{const child=frame.querySelector('.card-scale');if(child)child.style.transform='scale('+(frame.clientWidth/1080)+')';});}
function updatePreview(){const p=current();const el=$('.preview-panel');if(p&&el){el.outerHTML=preview(p);fitCards();observeFrames();}}
function observeFrames(){resizeObserver?.disconnect();resizeObserver=new ResizeObserver(()=>fitCards());document.querySelectorAll('.preview-frame').forEach(el=>resizeObserver.observe(el));}
function render(){
  const p=current();if(state.view==='work'&&!p)state.view='library';
  let content=state.view==='covers'?coverLibrary(state.projects):state.view==='guide'?creationGuide():state.view==='materials'?materialPage():state.view==='rules'?rulesView():state.view==='library'?library():stepNav(p)+(state.stage==='content'?contentView(p):state.stage==='cover'?coverView(p):state.stage==='design'?designView(p):state.stage==='review'?reviewView(p):draftsView(p));
  $('#app').innerHTML=`<div class="app-shell">${sidebar()}<main class="main">${header()}${content}</main></div>`;fitCards();observeFrames();if(state.view==='work'&&state.stage==='content')updateContentChecks();
}
async function openProject(id){await flush();state.projectId=id;const p=current();state.view='work';state.stage=p.stage==='drafts'&&cardsApproved(p)?'drafts':contentApproved(p)?'design':'content';state.selected=0;state.reviewed=new Set(cardsApproved(p)?p.content.cards.map((_,i)=>i):[]);render();}
async function goStage(stage){await flush();const p=current();if(!['content','cover'].includes(stage)&&!contentApproved(p)){toast('请先确认内容',true);return;}if(stage==='drafts'&&!cardsApproved(p)){toast('请先审核全部图卡',true);return;}state.stage=stage;render();window.scrollTo({top:0,behavior:'smooth'});}
function modal(title,body,buttons){const box=document.createElement('div');box.className='modal-backdrop';box.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${title}</h2><button class="btn text" data-dismiss aria-label="关闭">${icon('close',18)}</button></div>${body}<div class="modal-footer">${buttons}</div></section>`;document.body.append(box);box.addEventListener('click',e=>{if(e.target===box||e.target.closest('[data-dismiss]'))box.remove();});box.addEventListener('keydown',e=>{if(e.key==='Escape')box.remove();if(e.key==='Tab'){const f=[...box.querySelectorAll('button,input,textarea,select,a')];if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus();}}});setTimeout(()=>box.querySelector('input,button')?.focus(),0);return box;}
async function newProject(){const box=modal('新建一期内容',`<p>先给一个主题。封面可以稍后看参考再决定，不需要现在选真人或风格。</p><input id="new-topic" placeholder="例如：换台电脑，项目怎么迁移？" maxlength="60">`,`<button class="btn secondary" data-dismiss>取消</button><button class="btn primary" id="create-project">开始这一期</button>`);box.querySelector('#create-project').onclick=async()=>{const topic=box.querySelector('#new-topic').value.trim();if(!topic){toast('先写一个问题',true);return;}try{const p=seedProject();p.visual={theme:'sage',layout:'compact',creative:newCreative()};p.id='note-'+Date.now().toString(36);p.content.topic=topic;p.content.takeaway='';p.content.brief={audience:'',benefit:'',direction:'',references:[]};p.content.cards=[{kind:'editorial',eyebrow:'',title:topic,body:'',note:''}];for(const c of Object.values(p.platforms)){c.title='';c.body='';c.tags=[];}if(state.mode==='local'){const d=await api('/api/projects',p);state.projects.unshift(d.project);}else{state.projects.unshift(p);persistBrowser();}box.remove();await openProject(p.id);}catch(e){toast(e.message,true);}};}
function upgradeCover(p){const c=ensureCreative(p);if(c.workflow!==2){c.workflow=2;c.referenceId=null;c.reference=null;c.coverDirection='';c.coverCopy={headline:'',kicker:'',points:[],benefit:''};c.candidates=[];c.selectedCandidateId=null;if(c.result)c.candidates.push({...c.result,id:crypto.randomUUID()});}return c;}
function updateCoverControls(){const p=current(),c=creativeOf(p);if(state.stage!=='cover'||!c)return;const errors=creationErrors(p);try{validateCreative(p);}catch(e){errors.push(e.message);}const status=$('[data-cover-status]');if(status)status.textContent=errors.length?errors.join('；'):'参考与素材已准备，可以生成候选。';const task=$('[data-action="cover-task"]');if(task)task.disabled=Boolean(errors.length);const upload=$('[data-cover-result]');if(upload)upload.disabled=Boolean(errors.length);const key=creativeInputKey(p);document.querySelectorAll('.cover-candidate').forEach(el=>{const button=el.querySelector('[data-action="cover-select"]'),x=c.candidates.find(x=>x.id===button?.dataset.candidate);if(!x)return;const stale=x.inputFingerprint!==key,active=!stale&&x.id===c.selectedCandidateId;button.disabled=stale||Boolean(errors.length);button.textContent=active?'当前封面':'选为本期封面';button.className='btn '+(active?'primary':'secondary');el.classList.toggle('chosen',active);el.querySelector('.cover-reference-copy p').textContent=stale?'输入已变更 · 保留作对比，需要重新生成':active?'已选为本期封面 · 尚待图卡审核':'当前输入的候选 · 等待挑选';});const label=$('[data-cover-selection-status]');if(label)label.textContent=currentCover(p)?'本期封面已选；生成与选择不代表最终审核。':'本期封面等待挑选。';}
function ensureCreative(p){return p.visual.creative||(p.visual.creative=newCreative());}
function visualChanged(){const p=current();invalidateVisual(p);state.reviewed.clear();queueSave();render();}
async function readPhoto(file){if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>6*1024*1024)throw Error('请选择6MB以内的PNG、JPEG或WebP图片');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('图片读取失败'));r.readAsDataURL(file);});if(!imageDataValid(data))throw Error('图片内容与格式不匹配');return {name:file.name,data};}
async function uploadPortrait(file){await flush();const p=current(),photo=await readPhoto(file),c=ensureCreative(p);c.mode='portrait';c.portrait=photo;visualChanged();await flush();toast('本人照片已保存；选好参考后生成候选。');}
async function uploadCover(file){await flush();const p=current();if(creationErrors(p).length)throw Error(creationErrors(p).join('；'));const image=await readPhoto(file),key=creativeInputKey(p);if(state.mode==='local'){const d=await api('/api/projects/'+p.id+'/cover-import',{revision:p.revision,inputFingerprint:key,...image});Object.assign(p,d.project);state.reviewed.clear();render();}else{const c=ensureCreative(p);if(c.workflow===2){c.candidates.push({...image,inputFingerprint:key,id:crypto.randomUUID()});validateProject(p);}else c.result={...image,inputFingerprint:key};visualChanged();await flush();}toast('已加入候选，请检查后挑选本期封面。');}
async function copyTask(title,text){try{await navigator.clipboard.writeText(text);toast('任务已复制，请发到当前 Codex 对话。');}catch{modal(title,`<textarea rows="12" readonly>${esc(text)}</textarea>`,'<button class="btn secondary" data-dismiss>关闭</button>');}}
async function requestCover(){await flush();const p=current();if(state.mode!=='local')throw Error('请启动本机服务后执行真人封面生成任务，照片已保留在当前浏览器。');await copyTask('直接生成真人封面',coverTask(p,location.origin));}

function ensureBrief(p){return p.content.brief||(p.content.brief={audience:'',benefit:'',direction:'',references:[]});}
async function addReferences(files){const p=current(),b=ensureBrief(p),list=[...files];if(b.references.length+list.length>4)throw new Error('本机每期最多保存4张参考图');const refs=[];for(const file of list){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024)throw new Error('参考图请使用2MB以内的PNG、JPEG或WebP');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('参考图读取失败'));reader.readAsDataURL(file);});refs.push({name:file.name,note:'',data});}b.references.push(...refs);mutateContent();await flush();render();toast('参考图已保存。创作时按你的说明分析，不自动放进成图。');}
async function creationRequest(p){await flush();const b=p.content.brief||{audience:'',benefit:'',direction:'',references:[]};const text=`请完成工作台项目 ${p.id} 的内容创作：${p.content.topic}。读取 ${location.origin}/api/projects，结合本期事实与材料。受众：${b.audience||'外行读者'}；期望收获：${b.benefit||'结合选题给出明确收益'}；方向：${b.direction||'用具体案例解释'}。参考图保存在content.brief.references，先查看。正文与HTML/SVG内页保留案例、入口、条件和验收方法，内容与成图交给用户审核。封面是独立板块，可以稍后看参考再定，不要求先选真人、风格或生成封面，也不静默修改已确认正文。`;await copyTask('给 Codex 的创作任务',text);}


function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),20000);}
function backup(){download(new Blob([JSON.stringify({schema:1,exportedAt:new Date().toISOString(),projects:state.projects},null,2)],{type:'application/json'}),'小苋内容备份-'+new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'})+'.json');toast('内容备份已下载');}
async function importProjects(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>200*1024*1024)throw new Error('内容备份不能超过200MB');const data=JSON.parse(await file.text()),list=data.projects||[data];if(!Array.isArray(list)||list.length>100)throw new Error('项目文件格式错误');for(const raw of list){const p=structuredClone(validateProject(raw));p.id='import-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);p.revision=0;invalidateContent(p);for(const c of Object.values(p.platforms)){c.delivery=null;c.history=[];}if(state.mode==='local'){const d=await api('/api/projects',p);state.projects.unshift(d.project);}else state.projects.unshift(p);}if(state.mode==='browser')persistBrowser();render();toast('已导入内容，需重新确认和审核');}catch(e){toast(e.message,true);}};input.click();}
function showBusy(label){state.busy=true;const b=document.createElement('div');b.className='busy-screen';b.innerHTML=`<div class="spinner"></div><strong>${esc(label)}</strong><span class="small muted">请保持页面打开</span>`;document.body.append(b);}
function hideBusy(){state.busy=false;document.querySelector('.busy-screen')?.remove();}
function checkPoster(node){const area=node.getBoundingClientRect();for(const child of node.querySelectorAll('.poster-header,.poster-eyebrow,.poster-title,.poster-body,.poster-visual,.step-list,.prompt-box,.poster-note,.poster-footer,.content-block,.sc-header,.sc-title,.sc-block,.sc-note,.sc-footer,.sc-pending')){if(!child.getClientRects().length)continue;const box=child.getBoundingClientRect();if(box.bottom>area.bottom-24||box.right>area.right+1)throw new Error('图卡内容超出画布，请调整编排、拆页或修改内容');}const title=node.querySelector('.poster-title,.sc-title');if(title&&title.scrollWidth>title.clientWidth+1)throw new Error('标题超出当前版面，请调整换行、编排或内容');}
async function renderPng(p,i){const host=$('#export-host');host.innerHTML=poster(p,i);await document.fonts.ready;const node=host.firstElementChild;checkPoster(node);const data=await toPng(node,{width:1080,height:1440,pixelRatio:1,skipFonts:true});host.innerHTML='';return data;}
async function imageBundle(p){const images=[];for(let i=0;i<p.content.cards.length;i++)images.push(await renderPng(p,i));return images;}
async function pack(){await flush();const p=current();if(!cardsApproved(p))throw new Error('图卡尚未审核');const key=state.platform,check=validatePlatform(p,key);if(check.errors.length)throw new Error(check.errors.join('；'));showBusy('正在导出审核版图片与配文…');try{const images=await imageBundle(p),zip=new JSZip(),copy=p.platforms[key];images.forEach((image,i)=>zip.file('images/'+String(i+1).padStart(2,'0')+'.png',image.split(',')[1],{base64:true}));zip.file('配文.txt',copy.title+'\n\n'+copy.body+'\n\n'+copy.tags.map(t=>'#'+t).join(' '));const css=await (await fetch('./styles.css')).text();zip.file('图卡源文件.html','<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>'+esc(p.content.topic)+'</title><style>'+css+'body{display:flex;flex-direction:column;gap:40px;padding:30px;background:#e9eddf}.poster{flex-shrink:0}</style>'+p.content.cards.map((_,i)=>poster(p,i)).join('')+'</html>');zip.file('审核记录.json',JSON.stringify({topic:p.content.topic,cardApproval:p.cardApproval,contentApproval:p.contentApproval,platform:key,copy,visual:p.visual,cardFingerprint:cardKey(p)},null,2));for(const lib of ['lucide','tabler'])zip.file('许可/'+lib+'.txt',await (await fetch('./licenses/'+lib+'.txt')).text());zip.file('使用说明.txt','这是已审核图卡与平台配文。\n1. 将 images 中的图片按编号添加。\n2. 填入配文.txt 中的标题、说明和话题。\n3. 保存到草稿，最终发布由你执行。\n不包含公众号凭证。');download(await zip.generateAsync({type:'blob'}),'小苋-'+PLATFORMS[key].name+'-'+p.content.topic+'.zip');toast('交付包已下载，包含 PNG、配文和 HTML 源文件');}finally{hideBusy();}}
async function previewPng(){await flush();const p=current();showBusy('正在导出当前图卡…');try{const data=await renderPng(p,state.selected);const blob=await (await fetch(data)).blob();download(blob,'审核预览-'+String(state.selected+1).padStart(2,'0')+'.png');toast('预览图已下载；平台草稿仍需全部图卡审核。');}finally{hideBusy();}}
async function confirmContent(){await flush();const p=current(),errors=validateContent(p);if(errors.length)throw new Error(errors.join('；'));if(state.mode==='local'){const d=await api('/api/projects/'+p.id+'/content-approve',{revision:p.revision});Object.assign(p,d.project);}else{p.contentApproval={fingerprint:contentKey(p),at:new Date().toISOString(),by:'user'};p.stage='design';persistBrowser();}state.stage='design';render();window.scrollTo({top:0});toast('内容已确认，接下来只调整视觉。');}
async function confirmCards(){await flush();const p=current();if(coverErrors(p).length)throw Error(coverErrors(p).join('；'));if(state.reviewed.size!==p.content.cards.length)throw new Error('请逐张检查全部图卡');showBusy('正在核对全部图卡的版面…');try{const host=$('#export-host');for(let i=0;i<p.content.cards.length;i++){host.innerHTML=poster(p,i);checkPoster(host.firstElementChild);}host.innerHTML='';}finally{hideBusy();}const box=modal('确认这一版图卡',`<p>你已检查全部 ${p.content.cards.length} 张图。确认后，这一版将用于三端草稿。</p><p>之后修改文字或视觉，需要重新审核；平台配文可独立调整。</p>`,`<button class="btn secondary" data-dismiss>再看一遍</button><button class="btn primary" id="approve-final">确认并进入草稿 ${icon('check',15)}</button>`);box.querySelector('#approve-final').onclick=async()=>{try{if(state.mode==='local'){const d=await api('/api/projects/'+p.id+'/cards-approve',{revision:p.revision,cardFingerprint:cardKey(p),viewedCount:state.reviewed.size});Object.assign(p,d.project);}else{p.cardApproval={fingerprint:cardKey(p),at:new Date().toISOString(),by:'user'};p.stage='drafts';persistBrowser();}box.remove();state.stage='drafts';render();window.scrollTo({top:0});toast('图卡已审核，三端草稿已解锁。');}catch(e){toast(e.message,true);}};}
async function fillWechat(){await flush();const p=current();if(!cardsApproved(p))throw new Error('请先审核图卡');if(state.mode!=='local'||!state.wechat)throw new Error('公众号接口未连接');const v=validatePlatform(p,'wechat');if(v.errors.length)throw new Error(v.errors.join('；'));const box=modal('填写公众号草稿',`<p>将使用已审核的 ${p.content.cards.length} 张图和当前公众号配文创建多图草稿。</p><p>此操作只保存草稿，正式发布由你在公众号后台完成。</p>`,`<button class="btn secondary" data-dismiss>返回</button><button class="btn primary" id="fill-final">填写草稿 ${icon('upload',15)}</button>`);box.querySelector('#fill-final').onclick=async()=>{box.remove();showBusy('正在导出图卡并填写公众号草稿…');try{const images=await imageBundle(p);const d=await api('/api/projects/'+p.id+'/draft',{revision:p.revision,cardFingerprint:cardKey(p),images});Object.assign(p,d.project);render();toast('已写入公众号草稿，并完成读回核对。');}catch(e){try{const d=await api('/api/projects',null,'GET');const saved=d.projects.find(x=>x.id===p.id);if(saved)Object.assign(p,saved);render();}catch{}toast(e.message,true);}finally{hideBusy();}};}
async function recordManual(){await flush();const p=current(),key=state.platform;if(!cardsApproved(p))throw new Error('请先审核图卡');const box=modal('记录草稿状态',`<p>请确认：你已把这一版图片和配文填入${PLATFORMS[key].name}草稿。</p><p>这个按钮只记录你的操作，不会自动上传，也不会发布。</p>`,`<button class="btn secondary" data-dismiss>还没填好</button><button class="btn primary" id="manual-final">是的，已填入草稿</button>`);box.querySelector('#manual-final').onclick=async()=>{try{if(state.mode==='local'){const d=await api('/api/projects/'+p.id+'/manual-draft',{revision:p.revision,platform:key});Object.assign(p,d.project);}else{p.platforms[key].delivery={status:'manual',at:new Date().toISOString(),cardFingerprint:cardKey(p),by:'user'};persistBrowser();}box.remove();render();toast('已记录手动填写状态。');}catch(e){toast(e.message,true);}};}
async function refreshProject(id){const data=await api('/api/projects',null,'GET'),saved=data.projects.find(x=>x.id===id),p=current();if(saved&&p?.id===id)Object.assign(p,saved);}
async function watchDraftJob(job,box){
  const terminal=new Set(['draft','filled','needs_attention','error']);
  while(document.body.contains(box)){
    const data=await api('/api/draft-jobs/'+job.id,null,'GET'),j=data.job,status=box.querySelector('[data-job-status]'),message=box.querySelector('[data-job-message]');
    if(status)status.textContent=draftStatus(j);if(message)message.textContent=j.message||'';
    if(terminal.has(j.status)){await refreshProject(j.projectId);render();if(j.status==='draft')toast('草稿已保存，请到创作中心做最后核对。');else if(j.status==='error')toast(j.message,true);return;}
    await new Promise(resolve=>setTimeout(resolve,1500));
  }
}
async function fillCreatorDraft(){
  await flush();const p=current(),key=state.platform;if(!cardsApproved(p))throw new Error('请先审核图卡');if(state.mode!=='local'||!state.draftAutomation)throw new Error('本机自动填写未连接');if(state.platformSessions?.[key]?.status!=='logged_in')throw new Error('请先检查并完成'+PLATFORMS[key].name+'扫码登录');
  const check=validatePlatform(p,key);if(check.errors.length)throw new Error(check.errors.join('；'));
  showBusy('正在导出审核版图卡…');
  try{
    const images=await imageBundle(p),data=await api('/api/projects/'+p.id+'/draft-job',{revision:p.revision,platform:key,cardFingerprint:cardKey(p),images});Object.assign(p,data.project);
    const box=modal('正在填写'+PLATFORMS[key].name+'草稿',`<div class="job-progress"><span class="badge" data-job-status>${draftStatus(data.job)}</span><p data-job-message>${esc(data.job.message)}</p></div><div class="info-box">如果 Chrome 显示登录页，请扫码登录。登录状态只保存在本机独立浏览器资料中；最终发布仍由你完成。</div>`,`<button class="btn secondary" data-dismiss>关闭进度窗口</button>`);
    watchDraftJob(data.job,box).catch(error=>toast(error.message,true));
  }finally{hideBusy();}
}
async function checkPlatformLogin(){
  const key=state.platform;if(!['xiaohongshu','douyin'].includes(key))return;
  const data=await api('/api/platform-sessions/'+key+'/check',{}),box=modal('检查'+PLATFORMS[key].name+'登录状态',`<div class="job-progress"><span class="badge" data-job-status>${draftStatus(data.job)}</span><p data-job-message>${esc(data.job.message)}</p></div><div class="info-box">请在打开的独立 Chrome 中扫码登录。这里只检查登录，不上传图卡、不填写内容。</div>`,`<button class="btn secondary" data-dismiss>关闭进度窗口</button>`);
  const terminal=new Set(['logged_in','error']);
  while(document.body.contains(box)){
    const result=await api('/api/draft-jobs/'+data.job.id,null,'GET'),job=result.job;box.querySelector('[data-job-status]').textContent=draftStatus(job);box.querySelector('[data-job-message]').textContent=job.message||'';
    if(terminal.has(job.status)){const h=await api('/api/health',null,'GET');state.platformSessions=h.platformSessions||state.platformSessions;render();toast(job.status==='logged_in'?PLATFORMS[key].name+'登录状态已确认':job.message,job.status==='error');return;}
    await new Promise(resolve=>setTimeout(resolve,1500));
  }
}

document.addEventListener('input',e=>{if(e.target.hasAttribute('data-cover-copy')){const p=current(),c=upgradeCover(p);c.coverCopy=c.coverCopy||{headline:'',kicker:'',points:[],benefit:''};const key=e.target.dataset.coverCopy;c.coverCopy[key]=key==='points'?e.target.value.split('\n').filter(x=>x.trim()):e.target.value;invalidateVisual(p);state.reviewed.clear();queueSave();updateCoverControls();return;}if(e.target.hasAttribute('data-cover-direction')){const p=current();upgradeCover(p).coverDirection=e.target.value;invalidateVisual(p);state.reviewed.clear();queueSave();return;}
  const field=e.target.dataset.field,p=current();if(!p||state.busy)return;
  if(e.target.dataset.blockField){const b=p.content.cards[state.selected].blocks[Number(e.target.dataset.blockIndex)];b[e.target.dataset.blockField]=e.target.value;mutateContent();return;}
  if(e.target.dataset.referenceNote!==undefined){ensureBrief(p).references[Number(e.target.dataset.referenceNote)].note=e.target.value;mutateContent();return;}
  if(!field)return;
  const value=e.target.value;
  if(field.startsWith('brief-')){ensureBrief(p)[field.slice(6)]=value;mutateContent();}
  else if(field==='topic'||field==='takeaway'){p.content[field]=value;mutateContent();}
  else if(field.startsWith('card-')){p.content.cards[state.selected][field.slice(5)]=value;mutateContent();}
  else if(field==='review-note'){p.reviewNote=value;queueSave();}
  else if(field.startsWith('platform-')){
    const copy=p.platforms[state.platform];if(copy.delivery){copy.history=copy.history||[];copy.history.push(copy.delivery);copy.delivery=null;}
    if(field==='platform-tags')copy.tags=value.split(/[\s,，]+/).filter(Boolean).map(x=>x.replace(/^#+/,''));else copy[field==='platform-title'?'title':'body']=value;
    queueSave();$('[data-platform-checks]').innerHTML=platformChecks(p,state.platform);$('[data-tag-list]').innerHTML=copy.tags.map(t=>`<span class="topic-tag">#${esc(t)}</span>`).join('');const errors=validatePlatform(p,state.platform).errors;document.querySelectorAll('[data-action="package"],[data-action="wechat-draft"],[data-action="manual-draft"],[data-action="auto-draft"]').forEach(el=>el.disabled=errors.length>0||(el.dataset.action==='wechat-draft'&&(state.mode!=='local'||!state.wechat)));
  }
  const counter=document.querySelector('[data-count="'+field+'"]');if(counter)counter.textContent=count(value)+' 字';
});
document.addEventListener('change',async e=>{if(e.target.hasAttribute('data-cover-direction')||e.target.hasAttribute('data-cover-copy')){updateCoverControls();return;}if(e.target.hasAttribute('data-composition-upload')){try{await flush();const c=upgradeCover(current());c.reference=await readPhoto(e.target.files[0]);c.referenceId='custom';visualChanged();await flush();}catch(error){toast(error.message,true);}return;}if(e.target.hasAttribute('data-portrait-upload')){try{await uploadPortrait(e.target.files[0]);}catch(error){toast(error.message,true);}return;}if(e.target.hasAttribute('data-cover-result')){try{await uploadCover(e.target.files[0]);}catch(error){toast(error.message,true);}return;}if(e.target.dataset.referenceUpload!==undefined){try{await addReferences(e.target.files);}catch(error){toast(error.message,true);}return;}if(e.target.dataset.field==='card-kind'){const p=current();p.content.cards[state.selected].kind=e.target.value;mutateContent();}if(e.target.dataset.blockField==='type'){mutateContent();render();}});
document.addEventListener('click',async e=>{
  const el=e.target.closest('button[data-action],button[data-open],button[data-stage],button[data-select],button[data-theme],button[data-layout],button[data-page-layout],button[data-platform],button[data-reviewed],button[data-filter]');if(!el||el.disabled||state.busy)return;
  try{
    const p=current();
    if(el.dataset.open){await openProject(el.dataset.open);return;}
    if(el.dataset.stage){await goStage(el.dataset.stage);return;}
    if(el.dataset.select!==undefined){await flush();state.selected=Number(el.dataset.select);render();return;}
    if(el.dataset.filter){state.filter=el.dataset.filter;render();return;}
    if(el.dataset.theme||el.dataset.layout){p.visual[el.dataset.theme?'theme':'layout']=el.dataset.theme||el.dataset.layout;invalidateVisual(p);state.reviewed.clear();queueSave();render();return;}
    if(el.dataset.pageLayout){p.visual.pageLayouts=p.visual.pageLayouts||{};p.visual.pageLayouts[state.selected]=el.dataset.pageLayout;invalidateVisual(p);state.reviewed.clear();queueSave();render();return;}
    if(el.dataset.platform){await flush();state.platform=el.dataset.platform;render();return;}
    if(el.dataset.reviewed!==undefined){const i=Number(el.dataset.reviewed);state.reviewed.has(i)?state.reviewed.delete(i):state.reviewed.add(i);render();return;}
    switch(el.dataset.action){
      case 'cover-mode':{await flush();const c=upgradeCover(p);c.mode=el.dataset.mode;visualChanged();await flush();break;}
      case 'creative-style':{await flush();ensureCreative(p).style=el.dataset.style;visualChanged();await flush();break;}
      case 'remove-portrait':{await flush();const c=ensureCreative(p);c.portrait=null;visualChanged();await flush();break;}
      case 'covers':await flush();state.view='covers';render();window.scrollTo({top:0});break;
      case 'cover-open':await openProject(el.dataset.project);await goStage('cover');break;
      case 'cover-reference':{await flush();const c=upgradeCover(p),r=coverReference(el.dataset.reference);c.referenceId=r.id;c.mode=r.mode;visualChanged();await flush();toast('参考已选，接下来准备素材。');break;}
      case 'use-custom-reference':{await flush();const c=upgradeCover(p);if(!c.reference)throw Error('请先上传构图参考');c.referenceId='custom';visualChanged();await flush();break;}
      case 'remove-composition':{await flush();const c=upgradeCover(p);c.reference=null;if(c.referenceId==='custom')c.referenceId=null;visualChanged();await flush();break;}
      case 'cover-reference-zoom':{const r=coverReference(el.dataset.reference);modal(r.name,`<div class="cover-reference-zoom">${referenceVisual(r)}</div><p>${esc(r.description)}</p><p class="small muted">原创构图示例，非本人照片。关闭后点击“参考这张”选择。</p>`,'<button class="btn secondary" data-dismiss>关闭</button>');break;}
      case 'cover-candidate-zoom':{const x=creativeOf(p).candidates.find(x=>x.id===el.dataset.candidate);modal(x.name,`<img class="cover-full" src="${esc(x.data)}" alt="${esc(x.name)}"><p class="small muted">检查本人辨识度、标题、物件、裁切与主题关系；放大查看不代表选中或审核。</p>`,'<button class="btn secondary" data-dismiss>关闭</button>');break;}
      case 'cover-select':{await flush();const c=creativeOf(p),x=c.candidates.find(x=>x.id===el.dataset.candidate);if(!x||x.inputFingerprint!==creativeInputKey(p))throw Error('输入已变化，请重新生成');if(state.mode==='local'){const d=await api('/api/projects/'+p.id+'/cover-select',{revision:p.revision,candidateId:x.id});Object.assign(p,d.project);state.reviewed.clear();render();}else{c.selectedCandidateId=x.id;c.result={...x};visualChanged();await flush();}toast('已选为本期封面，仍需逐张审核图卡。');break;}
      case 'cover-candidate-remove':{await flush();const c=creativeOf(p);c.candidates=c.candidates.filter(x=>x.id!==el.dataset.candidate);if(c.selectedCandidateId===el.dataset.candidate){c.selectedCandidateId=null;c.result=null;}visualChanged();await flush();break;}
      case 'cover-task':await requestCover();break;
      case 'library':await flush();state.view='library';render();break;
      case 'rules':await flush();state.view='rules';render();window.scrollTo({top:0});break;
      case 'guide':await flush();state.view='guide';render();window.scrollTo({top:0});break;
      case 'materials':await flush();state.view='materials';render();window.scrollTo({top:0});break;
      case 'choose-icon':await flush();chooseIcon();break;
      case 'remove-icon':delete p.visual.artwork[state.selected];invalidateVisual(p);state.reviewed.clear();queueSave();render();break;
      case 'new':await flush();await newProject();break;
      case 'backup':await flush();backup();break;
      case 'import':await flush();await importProjects();break;
      case 'add-block':{const c=p.content.cards[state.selected];c.blocks=c.blocks||[];if(c.blocks.length<20)c.blocks.push({type:'text',heading:'',text:''});mutateContent();render();break;}
      case 'remove-block':p.content.cards[state.selected].blocks.splice(Number(el.dataset.index),1);mutateContent();render();break;
      case 'remove-reference':ensureBrief(p).references.splice(Number(el.dataset.index),1);mutateContent();render();break;
      case 'creation-request':await creationRequest(p);break;
      case 'add-card':if(p.content.cards.length>=MAX_CARDS)break;p.content.cards.push({kind:'editorial',eyebrow:'',title:'',body:'',note:''});state.selected=p.content.cards.length-1;invalidateContent(p);queueSave();render();break;
      case 'remove-card':if(p.content.cards.length>1){p.content.cards.splice(state.selected,1);for(const key of ['artwork','pageLayouts'])if(p.visual[key])p.visual[key]=Object.fromEntries(Object.entries(p.visual[key]).filter(([k])=>Number(k)!==state.selected).map(([k,v])=>[Number(k)>state.selected?Number(k)-1:k,v]));state.selected=Math.min(state.selected,p.content.cards.length-1);invalidateContent(p);queueSave();render();}break;
      case 'confirm-content':await confirmContent();break;
      case 'go-review':await goStage('review');break;
      case 'review-all':state.reviewed=new Set(p.content.cards.map((_,i)=>i));render();await confirmCards();break;
      case 'confirm-cards':await confirmCards();break;
      case 'preview-png':await previewPng();break;
      case 'package':await pack();break;
      case 'copy':{const c=p.platforms[state.platform],text=c.title+'\n\n'+c.body+'\n\n'+c.tags.map(t=>'#'+t).join(' ');try{await navigator.clipboard.writeText(text);toast('配文已复制');}catch{modal('复制配文',`<textarea rows="9" readonly>${esc(text)}</textarea>`,`<button class="btn secondary" data-dismiss>关闭</button>`);}break;}
      case 'wechat-draft':await fillWechat();break;
      case 'platform-login':await checkPlatformLogin();break;
      case 'auto-draft':await fillCreatorDraft();break;
      case 'manual-draft':await recordManual();break;
    }
  }catch(err){toast(err.message,true);}
});
window.addEventListener('beforeunload',e=>{if(hasUnsaved||state.busy){e.preventDefault();e.returnValue='';}});
async function init(){
  try{const h=await api('/api/health',null,'GET');if(h.mode!=='local')throw new Error('browser');const d=await api('/api/projects',null,'GET');state.mode='local';state.wechat=h.wechat;state.draftAutomation=Boolean(h.draftAutomation);state.platformSessions=h.platformSessions||state.platformSessions;state.projects=d.projects.map(validateProject);}
  catch{try{state.projects=JSON.parse(localStorage.getItem('xiaoxian-studio-v1')||'null')?.map(validateProject)||[seedProject()];}catch{state.projects=[seedProject()];}try{persistBrowser();}catch{toast('浏览器存储不可用，请使用本机工作台。',true);}}
  saveLabel('已保存');const params=new URLSearchParams(location.search),id=params.get('project');if(id&&state.projects.some(p=>p.id===id)){state.projectId=id;state.view='work';state.stage=params.get('stage')==='cover'?'cover':'content';}render();
}
init();
